package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.special.Gamma;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math3.exception.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for PoissonDistributionImpl constructor.
 */
public class PoissonDistributionImpl_PoissonDistributionImpl_TriageGen2Test {

    @Test
    public void testConstructorWithValidParameters() {
        double p = 5.0;
        double epsilon = 1e-10;
        int maxIterations = 100;

        PoissonDistributionImpl distribution = new PoissonDistributionImpl(p, epsilon, maxIterations);

        assertEquals(p, distribution.getMean(), 1e-15);
    }

    @Test
    public void testConstructorWithPZeroThrowsException() {
        double p = 0.0;
        double epsilon = 1e-10;
        int maxIterations = 100;

        try {
            new PoissonDistributionImpl(p, epsilon, maxIterations);
            org.junit.Assert.fail("Expected MathRuntimeException was not thrown");
        } catch (MathRuntimeException e) {
            // Success: exception caught
        }
    }

    @Test
    public void testConstructorWithPNegativeThrowsException() {
        double p = -1.0;
        double epsilon = 1e-10;
        int maxIterations = 100;

        try {
            new PoissonDistributionImpl(p, epsilon, maxiterations);
            org.junit.Assert.fail("Expected MathRuntimeException was not thrown");
        } catch (MathRuntimeException e) {
            // Success: exception caught
        }
    }

    @Test
    public void testConstructorSingleParam() {
        double p = 4.5;
        PoissonDistributionImpl distribution = new PoissonDistributionImpl(p);
        assertEquals(p, distribution.getMean(), 1e-15);
    }

    @Test
    public void testConstructorTwoParamsEpsilon() {
        double p = 4.5;
        double epsilon = 1e-5;
        PoissonDistributionImpl distribution = new PoissonDistributionImpl(p, epsilon);
        assertEquals(p, distribution.getMean(), 1e-15);
    }

    @Test
    public void testConstructorTwoParamsMaxIterations() {
        double p = 4.5;
        int maxIterations = 50;
        PoissonDistributionImpl distribution = new PoissonDistributionImpl(p, maxIterations);
        assertEquals(p, distribution.getMean(), 1e-15);
    }
}
